package com.wealthflow;
import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.List;import static org.assertj.core.api.Assertions.assertThat;
class AllocationEngineTest {
 @Test void splitsAnIndivisibleFinalCentAndReconcilesExactly(){var r=AllocationEngine.allocate(new BigDecimal("100.00"),List.of(new AllocationEngine.Share("A",new BigDecimal("33333")),new AllocationEngine.Share("B",new BigDecimal("33333")),new AllocationEngine.Share("C",new BigDecimal("33334"))));assertThat(r.lines()).extracting(AllocationEngine.Line::finalAmount).containsExactly(new BigDecimal("33.33"),new BigDecimal("33.33"),new BigDecimal("33.34"));assertThat(r.residual()).isEqualByComparingTo("0.01");assertThat(r.reconciledTotal()).isEqualByComparingTo("100.00");assertThat(r.reconciled()).isTrue();}
 @Test void resolvesTiesByAscendingRecipientIdAndIsRepeatable(){var shares=List.of(new AllocationEngine.Share("B",BigDecimal.ONE),new AllocationEngine.Share("A",BigDecimal.ONE),new AllocationEngine.Share("C",BigDecimal.ONE));var first=AllocationEngine.allocate(new BigDecimal("0.01"),shares);var second=AllocationEngine.allocate(new BigDecimal("0.01"),shares);assertThat(first.lines()).containsExactlyElementsOf(second.lines());assertThat(first.lines().get(1).id()).isEqualTo("A");}
 @Test void distributesMultipleResidualMinorUnits(){var r=AllocationEngine.allocate(new BigDecimal("0.05"),List.of(new AllocationEngine.Share("A",BigDecimal.ONE),new AllocationEngine.Share("B",BigDecimal.ONE),new AllocationEngine.Share("C",BigDecimal.ONE)));assertThat(r.lines()).extracting(AllocationEngine.Line::finalAmount).containsExactly(new BigDecimal("0.02"),new BigDecimal("0.02"),new BigDecimal("0.01"));assertThat(r.reconciledTotal()).isEqualByComparingTo("0.05");}
}
